import sys

def min_operations(a, b):
    diff = abs(a - b)
    if diff == 0:
        return 0

    # Binary search to find the minimum k such that k * (k + 1) / 2 >= diff
    left, right = 0, int(diff**0.5) + 1
    while left < right:
        mid = (left + right) // 2
        if mid * (mid + 1) // 2 < diff:
            left = mid + 1
        else:
            right = mid

    # Check if we can achieve the exact match with the found k
    if left * (left + 1) // 2 >= diff:
        return left
    else:
        return left + 1

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    t = int(data[index])
    index += 1
    results = []

    for _ in range(t):
        a = int(data[index])
        index += 1
        b = int(data[index])
        index += 1
        results.append(min_operations(a, b))

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
